import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第三十七卦 家人 风火家人 巽上离下","description":"周易 - 第三十七卦 家人 风火家人 巽上离下","frontmatter":{"title":"第三十七卦 家人 风火家人 巽上离下","description":"周易 - 第三十七卦 家人 风火家人 巽上离下"},"headers":[],"relativePath":"zh/classics/zhouyi/038.md","filePath":"zh/classics/zhouyi/038.md"}'),l={name:"zh/classics/zhouyi/038.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="家人" tabindex="-1">家人 <a class="header-anchor" href="#家人" aria-label="Permalink to “家人”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>利女贞。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>家人，女正位乎内，男正位乎外，男女正，天地之大义也。家人有严君焉，父母之谓也。父父，子子，兄兄，弟弟，夫夫，妇妇，而家道正；正家而天下定矣。</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>风自火出，家人；君子以言有物，而行有恒。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>闲有家，悔亡。象曰：闲有家，志未变也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>无攸遂，在中馈，贞吉。象曰：六二之吉，顺以巽也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>家人嗃嗃，悔厉吉；妇子嘻嘻，终吝。象曰：家人嗃嗃，未失也；妇子嘻嘻，失家节也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>富家，大吉。象曰：富家大吉，顺在位也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>王假有家，勿恤吉。象曰：王假有家，交相爱也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>有孚威如，终吉。象曰：威如之吉，反身之谓也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
